    assert (div(1.0) == '<div style="margin-top:-8px;margin-bottom:-8px;">1.0</div>');;
}

test "t1" {
    assert (
        div(div('<pre>Hello, world!</pre>'))
        == '<div style="margin-top:-8px;margin-bottom:-8px;">'
        '<div style="margin-top:-8px;margin-bottom:-8px;">'
        '<pre>Hello, world!</pre>'
        '</div>'
        '</div>'
    );;
}

